module asyn_fifo#(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output reg [WIDTH-1:0] rdata,
    output reg wfull,
    output reg rempty
);
parameter ADDR_WIDTH = $clog2(DEPTH);

input wclk;
input rclk;
input wrstn;
input rrstn;
input winc;
input rinc;
input [WIDTH-1:0] wdata;
output reg [WIDTH-1:0] rdata;
output reg wfull;
output reg rempty;
parameter WIDTH = 8;
parameter DEPTH = 16;
parameter ADDR_WIDTH = $clog2(DEPTH);

wire [ADDR_WIDTH:0] waddr_bin;
wire [ADDR_WIDTH:0] raddr_bin;
reg [ADDR_WIDTH:0] waddr;
reg [ADDR_WIDTH:0] raddr;
wire [WIDTH-1:0] wdata;
wire [WIDTH-1:0] rdata;
reg [ADDR_WIDTH:0] wptr;
reg [ADDR_WIDTH:0] rptr;
reg [ADDR_WIDTH:0] wptr_buff;
reg [ADDR_WIDTH:0] rptr_buff;
wire wen;
wire ren;
reg [ADDR_WIDTH:0] waddr;
reg [ADDR_WIDTH:0] raddr;
wire [WIDTH-1:0] wdata;
wire [WIDTH-1:0] rdata;
reg [ADDR_WIDTH:0] wptr;
reg [ADDR_WIDTH:0] rptr;
reg [ADDR_WIDTH:0] wptr_buff;
reg [ADDR_WIDTH:0] rptr_buff;
wire wen;
wire ren;

always @(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
        waddr <= 'd0;
    end
    else if(!wfull && winc) begin
        waddr <= waddr + 1'd1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
        raddr <= 'd0;
    end
    else if(!rempty && rinc) begin
        raddr <= raddr + 1'd1;
    end
end

assign waddr_bin = waddr;
assign raddr_bin = raddr;
assign waddr = waddr_bin;
assign raddr = raddr_bin;
assign wdata = wdata;
assign rdata = rdata;
assign wptr = waddr;
assign rptr = raddr;
always @(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
        wptr_buff <= 'd0;
    end
    else begin
        wptr_buff <= wptr;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
        rptr_buff <= 'd0;
    end
    else begin
        rptr_buff <= rptr;
    end
end

assign wptr_syn = wptr_buff;
assign rptr_syn = rptr_buff;

assign wen = !wfull && winc;
assign ren = !rempty && rinc;

always @(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
        waddr_bin <= 'd0;
    end
    else if(wen) begin
        waddr_bin <= waddr_bin + 'd1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
        raddr_bin <= 'd0;
    end
    else if(ren) begin
        raddr_bin <= raddr_bin + 'd1;
    end
end

assign waddr = waddr_bin;
assign raddr = raddr_bin;

assign wptr = waddr;
assign rptr = raddr;

assign wptr_buff = wptr;
assign rptr_buff = rptr;

assign wptr_syn = wptr_buff;
assign rptr_syn = rptr_buff;

assign wfull = (wptr == rptr_syn)? 1'b1 : 1'b0;
assign rempty = (rptr == wptr_syn)? 1'b1 : 1'b0;

endmodule
